import sys
import heapq

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    mst_cost = 0
    mst_edges = []
    for w, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_cost += w
            mst_edges.append((u, v, w))
    return mst_cost, mst_edges

def min_operations_to_unique_mst(n, edges):
    edges.sort()
    mst_cost, mst_edges = kruskal(n, edges)
    edge_count = [0] * (n + 1)
    for u, v, _ in mst_edges:
        edge_count[u] += 1
        edge_count[v] += 1
    candidate_edges = []
    for u, v, w in edges:
        if find(parent, u) != find(parent, v) or (edge_count[u] > 1 and edge_count[v] > 1):
            candidate_edges.append((w, u, v))
    operations = 0
    parent = list(range(n + 1))
    rank = [0 for _ in range(n + 1)]
    for w, u, v in mst_edges:
        union(parent, rank, u, v)
    for w, u, v in candidate_edges:
        if find(parent, u) != find(parent, v):
            if w < mst_cost:
                union(parent, rank, u, v)
            else:
                operations += 1
                union(parent, rank, u, v)
    return operations

